USE dave_kb;


-- ============================================================
-- Vocabulary Table: Dave's 300,000-word lexicon
-- ============================================================

CREATE TABLE IF NOT EXISTS vocabulary (
    id              BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    word            VARCHAR(128) NOT NULL,
    domain          VARCHAR(32) NOT NULL COMMENT 'Academic domain (PHIL, MATH, PHYS, MED, etc.)',
    definition      TEXT NOT NULL COMMENT 'Professional-grade definition',
    phrase          TEXT NOT NULL COMMENT 'Contextual phrase at 140+ IQ content level',
    iq_floor        INT UNSIGNED DEFAULT 140 COMMENT 'Minimum IQ level for natural comprehension',
    frequency       INT UNSIGNED DEFAULT 0 COMMENT 'How often Dave has used this word',
    last_used       TIMESTAMP NULL DEFAULT NULL,
    learned_at      TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    mastery_level   ENUM('encounter', 'comprehend', 'integrate', 'apply', 'master', 'conclude')
                    DEFAULT 'master' COMMENT 'Dave learning stage for this word',

    INDEX idx_word (word),
    INDEX idx_domain (domain),
    INDEX idx_mastery (mastery_level),
    FULLTEXT INDEX ft_definition (definition),
    FULLTEXT INDEX ft_phrase (phrase)
) ENGINE=InnoDB;

-- ============================================================
-- Vocabulary Metadata
-- ============================================================

CREATE TABLE IF NOT EXISTS vocabulary_metadata (
    id              INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    property_name   VARCHAR(64) NOT NULL UNIQUE,
    property_value  TEXT NOT NULL,
    updated_at      TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB;

ON DUPLICATE KEY UPDATE property_value = VALUES(property_value);

-- ============================================================
-- Load vocabulary from .lib file
-- ============================================================
-- The .lib file contains pipe-delimited entries:
--   word | domain | definition | phrase
--
-- Load with:
--   LOAD DATA LOCAL INFILE '/path/to/76_vocabulary_300k.lib'
--   INTO TABLE vocabulary
--   FIELDS TERMINATED BY ' | '
--   LINES TERMINATED BY '\n'
--   IGNORE 18 LINES
--   (word, domain, definition, phrase);
--
-- Or use the batch insert below for the curated high-value entries:

-- Curated high-value entries (hand-crafted definitions and phrases)

-- ============================================================
-- Grant Dave access
-- ============================================================

GRANT SELECT, INSERT, UPDATE ON dave_kb.vocabulary TO 'dave_ai'@'localhost';
GRANT SELECT, INSERT, UPDATE ON dave_kb.vocabulary_metadata TO 'dave_ai'@'localhost';
FLUSH PRIVILEGES;
