INSERT INTO vocabulary (word, domain, definition, phrase, iq_floor, mastery_level) VALUES
  ('ontological', 'PHIL', 'Relating to the nature of being and existence', 'The ontological commitment of our theory implies entities beyond the observable', 140, 'master'),
  ('epistemological', 'PHIL', 'Pertaining to the theory of knowledge, its scope and limits', 'The epistemological gap between justified belief and certain knowledge defines the human condition', 140, 'master'),
  ('phenomenological', 'PHIL', 'Relating to the structures of conscious experience', 'A phenomenological reduction brackets the natural attitude to reveal the essences of consciousness', 140, 'master'),
  ('hermeneutic', 'PHIL', 'Concerning interpretation, especially of texts and meaning', 'The hermeneutic circle demands we understand parts through the whole and the whole through parts', 140, 'master'),
  ('dialectical', 'PHIL', 'Relating to logical argumentation through thesis, antithesis, synthesis', 'Dialectical reasoning reveals that every position generates its own negation', 140, 'master'),
  ('teleological', 'PHIL', 'Directed toward a definite end or purpose', 'The teleological argument infers design from the apparent purposiveness of natural systems', 140, 'master'),
  ('deontological', 'PHIL', 'Relating to duty-based moral theory independent of consequences', 'A deontological framework holds that certain acts are intrinsically right regardless of outcome', 140, 'master'),
  ('axiological', 'PHIL', 'Pertaining to the study of values and value judgments', 'Axiological neutrality in research demands we separate factual claims from evaluative ones', 140, 'master'),
  ('apodeictic', 'PHIL', 'Clearly established or beyond dispute; necessarily true', 'Mathematical truths carry apodeictic certainty that empirical claims can never achieve', 140, 'master'),
  ('apodictic', 'PHIL', 'Expressing or of the nature of necessary truth', 'Apodictic knowledge proceeds from self-evident premises by rules of inference', 140, 'master'),
  ('a priori', 'PHIL', 'Knowledge independent of experience; before the fact', 'Kant argued that space and time are a priori forms of sensible intuition', 140, 'master'),
  ('a posteriori', 'PHIL', 'Knowledge derived from experience; after the fact', 'All empirical science yields a posteriori knowledge revisable in light of new evidence', 140, 'master'),
  ('noumenon', 'PHIL', 'A thing as it is in itself, independent of perception', 'The noumenon remains forever inaccessible to empirical investigation', 140, 'master'),
  ('qualia', 'PHIL', 'The subjective, conscious qualities of experience', 'Qualia present the hardest problem for physicalist theories of mind', 140, 'master'),
  ('dasein', 'PHIL', 'Being-there; human existence in its engaged worldliness', 'Dasein always finds itself already thrown into a world not of its choosing', 140, 'master'),
  ('weltanschauung', 'PHIL', 'A comprehensive worldview or philosophy of life', 'Every culture embodies a Weltanschauung that shapes its institutions', 140, 'master'),
  ('praxis', 'PHIL', 'Practice as distinguished from theory; practical action', 'Theory without praxis remains inert; praxis without theory remains blind', 140, 'master'),
  ('telos', 'PHIL', 'The ultimate aim or purpose of something', 'The telos of inquiry is truth; the telos of moral development is virtue', 140, 'master'),
  ('eudaimonia', 'PHIL', 'Human flourishing or well-being; the highest good', 'Aristotle held that eudaimonia consists in activity of soul in accordance with virtue', 140, 'master'),
  ('aletheia', 'PHIL', 'Truth as unconcealment; the disclosure of being', 'Heidegger retrieved aletheia as the originary sense of truth before correspondence', 140, 'master'),
  ('aporia', 'PHIL', 'An irresolvable internal contradiction or logical paradox', 'Socratic dialogue characteristically arrives at aporia, revealing the limits of the interlocutor\'s knowledge', 140, 'master'),
  ('intersubjectivity', 'PHIL', 'The shared, mutual understanding between persons', 'Intersubjectivity grounds the possibility of communication and shared meaning', 140, 'master'),
  ('solipsism', 'PHIL', 'The view that only one\'s own mind is sure to exist', 'The problem of other minds threatens to collapse into solipsism without a bridge to intersubjectivity', 140, 'master'),
  ('verisimilitude', 'PHIL', 'The appearance or semblance of truth; probability', 'Popper proposed verisimilitude as a measure of how close a theory approaches truth', 140, 'master'),
  ('incommensurable', 'PHIL', 'Having no common standard of measurement; incomparable', 'Kuhn argued that successive paradigms may be incommensurable', 140, 'master'),
  ('supervene', 'PHIL', 'To occur as an additional or consequent condition', 'Mental properties supervene on physical ones without being reducible to them', 140, 'master'),
  ('reify', 'PHIL', 'To treat an abstraction as if it were a concrete thing', 'We must not reify statistical constructs like intelligence into fixed essences', 140, 'master'),
  ('bifurcation', 'PHIL', 'Division into two sharply distinguished parts', 'Whitehead warned against the bifurcation of nature into primary and secondary qualities', 140, 'master'),
  ('sublation', 'PHIL', 'The process of cancellation and preservation in a higher unity', 'Hegelian sublation preserves what is rational in each moment while transcending its limitations', 140, 'master'),
  ('immanent', 'PHIL', 'Existing or operating within; inherent', 'An immanent critique judges a system by its own stated standards', 140, 'master'),
  ('transcendent', 'PHIL', 'Beyond ordinary experience; surpassing usual limits', 'The transcendent ideal of perfect justice regulates without being achievable', 140, 'master'),
  ('homeomorphism', 'MATH', 'A continuous bijection with continuous inverse between topological spaces', 'The coffee cup and donut are homeomorphic — topology studies what remains invariant under continuous deformation', 140, 'master'),
  ('isomorphism', 'MATH', 'A structure-preserving bijection between mathematical objects', 'Group isomorphism establishes that two groups have identical algebraic structure', 140, 'master'),
  ('diffeomorphism', 'MATH', 'A differentiable bijection with differentiable inverse between smooth manifolds', 'General relativity describes spacetime as a diffeomorphism-invariant theory', 140, 'master'),
  ('homotopy', 'MATH', 'A continuous deformation of one function into another', 'Homotopy equivalence captures the intuition that two spaces have the same shape', 140, 'master'),
  ('cohomology', 'MATH', 'A mathematical structure measuring holes and obstructions in spaces', 'De Rham cohomology connects differential forms to topological invariants', 140, 'master'),
  ('eigenvalue', 'MATH', 'A scalar by which an eigenvector is multiplied under a linear transformation', 'The eigenvalues of the Hamiltonian operator represent measurable energy levels', 140, 'master'),
  ('determinant', 'MATH', 'A scalar value encoding properties of a square matrix', 'A vanishing determinant indicates linear dependence among the column vectors', 140, 'master'),
  ('jacobian', 'MATH', 'The matrix of all first-order partial derivatives of a vector-valued function', 'The Jacobian determinant measures local volume change under a coordinate transformation', 140, 'master'),
  ('Laplacian', 'MATH', 'The divergence of the gradient; sum of second partial derivatives', 'The Laplacian operator governs diffusion, wave propagation, and potential theory', 140, 'master'),
  ('manifold', 'MATH', 'A topological space locally resembling Euclidean space', 'Spacetime is modeled as a four-dimensional pseudo-Riemannian manifold', 140, 'master'),
  ('tensor', 'MATH', 'A multilinear map generalizing scalars, vectors, and matrices', 'The stress-energy tensor encodes the density and flux of energy and momentum', 140, 'master'),
  ('stochastic', 'MATH', 'Randomly determined; involving a random variable', 'Stochastic processes model systems whose evolution involves fundamental randomness', 140, 'master'),
  ('ergodic', 'MATH', 'Having the property that time averages equal ensemble averages', 'Ergodic theory connects dynamical systems to statistical mechanics', 140, 'master'),
  ('bijective', 'MATH', 'Both injective and surjective; a one-to-one correspondence', 'A bijective function establishes that two sets have the same cardinality', 140, 'master'),
  ('surjective', 'MATH', 'Mapping onto the entire codomain; every output has a preimage', 'A surjective homomorphism maps the domain group onto the entire codomain group', 140, 'master'),
  ('injective', 'MATH', 'Preserving distinctness; different inputs yield different outputs', 'An injective function never maps two distinct elements to the same image', 140, 'master'),
  ('idempotent', 'MATH', 'Unchanged in value when multiplied or applied to itself', 'A projection operator is idempotent: applying it twice equals applying it once', 140, 'master'),
  ('commutative', 'MATH', 'Independent of order of operation; ab = ba', 'Matrix multiplication is not commutative, which encodes the non-commutativity of quantum observables', 140, 'master'),
  ('associative', 'MATH', 'Independent of grouping; (ab)c = a(bc)', 'Associativity ensures that long compositions can be parsed without ambiguity', 140, 'master'),
